<script>
  import Icon from '../../Icon/Icon.svelte'

  let {
    ref = $bindable(null),
    class: klass = '',
    icon = 'tabler:x',
    iconClass = '',
    target = null,
    children,
    ...rest
  } = $props()

  const targetAction = $derived(target ? 'hide' : null)

  function closeDrawer() {
    const popover =
      (target && document.querySelector(`#${target}`)) ||
      ref.closest('[popover]')
    popover.hidePopover()
  }
</script>

<button
  {...rest}
  aria-label="Close"
  class="button-icon {klass}"
  popovertarget={target}
  popovertargetaction={targetAction}
  bind:this={ref}
  onclick={closeDrawer}
>
  {#if children}
    {@render children()}
  {:else}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
